env = {
  _args = [
    "WARP_ENABLE_WAYLAND"
    "1"
  ];
};

device = [
  {
    name = "framework-laptop-16-keyboard-module---ansi-keyboard";
    kb_layout = "us";
    kb_variant = "colemak";
    kb_options = "ctrl:nocaps,ctrl:swapcaps";
  }
  {
    name = "at-translated-set-2-keyboard";
    kb_layout = "us";
    kb_variant = "colemak";
    kb_options = "ctrl:nocaps,ctrl:swapcaps";
  }
];

# exec-once equivalents. The module already emits a hyprland.start hook for
# the systemd/D-Bus activation env, so we only add our own programs.
on = {
  _args = [
    "hyprland.start"
    (mkLuaInline ''
      function()
        hl.exec_cmd("mako")
        hl.exec_cmd("hypr-fullscreen-inhibit")
        hl.exec_cmd("elephant")
      end'')
  ];
};

